CREATE TABLE bank_batches (org_id TEXT NOT NULL REFERENCES organizations(id), id TEXT NOT NULL, source_sha256 TEXT NOT NULL, metadata_json TEXT NOT NULL, imported_at TEXT NOT NULL, PRIMARY KEY(org_id,id), UNIQUE(org_id,source_sha256));
CREATE TABLE bank_heads (org_id TEXT NOT NULL REFERENCES organizations(id), id TEXT NOT NULL, batch_id TEXT NOT NULL, revision INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(org_id,id), FOREIGN KEY(org_id,batch_id) REFERENCES bank_batches(org_id,id));
CREATE TABLE bank_versions (org_id TEXT NOT NULL, question_id TEXT NOT NULL, revision INTEGER NOT NULL, content_json TEXT NOT NULL, content_hash TEXT NOT NULL, validation_json TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('pending','available','published','quarantined','withdrawn')), reviewed_by TEXT REFERENCES users(id), reviewed_at TEXT, actor_id TEXT REFERENCES users(id), action TEXT NOT NULL, note TEXT NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY(org_id,question_id,revision), FOREIGN KEY(org_id,question_id) REFERENCES bank_heads(org_id,id));
CREATE TRIGGER bank_version_advance AFTER INSERT ON bank_versions BEGIN UPDATE bank_heads SET revision=NEW.revision WHERE org_id=NEW.org_id AND id=NEW.question_id; END;
CREATE TRIGGER bank_version_immutable_update BEFORE UPDATE ON bank_versions BEGIN SELECT RAISE(ABORT,'bank versions immutable'); END;
CREATE TRIGGER bank_version_immutable_delete BEFORE DELETE ON bank_versions BEGIN SELECT RAISE(ABORT,'bank versions immutable'); END;
CREATE TABLE bank_reports (id TEXT PRIMARY KEY, org_id TEXT NOT NULL, question_id TEXT NOT NULL, question_revision INTEGER NOT NULL, reporter_id TEXT NOT NULL REFERENCES users(id), reason TEXT NOT NULL, created_at TEXT NOT NULL, resolved_by TEXT REFERENCES users(id), resolved_at TEXT, resolution TEXT, FOREIGN KEY(org_id,question_id,question_revision) REFERENCES bank_versions(org_id,question_id,revision));
CREATE INDEX bank_reports_question ON bank_reports(org_id,question_id,created_at);
CREATE TABLE bank_knowledge_levels (org_id TEXT NOT NULL REFERENCES organizations(id), knowledge_id TEXT NOT NULL, revision INTEGER NOT NULL, difficulty TEXT CHECK(difficulty IS NULL OR difficulty IN ('very_low','low','medium','high','very_high')), actor_id TEXT NOT NULL REFERENCES users(id), note TEXT NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY(org_id,knowledge_id,revision));
CREATE TRIGGER bank_knowledge_level_immutable_update BEFORE UPDATE ON bank_knowledge_levels BEGIN SELECT RAISE(ABORT,'knowledge levels immutable'); END;
CREATE TRIGGER bank_knowledge_level_immutable_delete BEFORE DELETE ON bank_knowledge_levels BEGIN SELECT RAISE(ABORT,'knowledge levels immutable'); END;
